const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PAGES=['home','kana','lessons','grammar','vocab','reading','listening','practice','progress','plan'];
const emptyState=()=>({version:2,completed:[],seen:[],attempts:0,correct:0,days:[],wordReviews:{},textDone:[],mistakes:{},history:[],daily:{},activeQuiz:null,plan:{target:'N2',minutes:40,start:'N5'},level:'N5'});
const validGrammar=new Set(grammar.map(x=>x.id)),validWords=new Set(words.map(x=>x.id)),validTexts=new Set([...readings,...listenings].map(x=>x.id));
const dateKey=()=>new Date().toLocaleDateString('sv-SE'),dateValid=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T12:00:00'));
function afterDays(n){const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('sv-SE');}
const num=(n,max=1e7)=>Number.isFinite(n)?Math.max(0,Math.min(max,Math.floor(n))):0;
function cleanState(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.completed))throw Error('记录格式不正确');const s=emptyState();if(typeof cleanStudyExtras==='function')Object.assign(s,cleanStudyExtras(raw));s.completed=[...new Set(raw.completed.filter(id=>validGrammar.has(id)))];s.seen=[...new Set((Array.isArray(raw.seen)?raw.seen:[]).filter(k=>typeof k==='string'&&kanaRows.some(r=>r[0].includes(k)&&k!==' ')))];s.attempts=num(raw.attempts);s.correct=Math.min(num(raw.correct),s.attempts);s.days=[...new Set((Array.isArray(raw.days)?raw.days:[]).filter(dateValid))];s.level=LEVELS.includes(raw.level)?raw.level:'N5';s.textDone=[...new Set((Array.isArray(raw.textDone)?raw.textDone:[]).filter(id=>validTexts.has(id)))];for(const [id,v]of Object.entries(raw.wordReviews||{})){if(validWords.has(id)&&v&&dateValid(v.due))s.wordReviews[id]={box:num(v.box,6),due:v.due,last:dateValid(v.last)?v.last:null};}for(const [id,v]of Object.entries(raw.mistakes||{})){if(questionById(id)&&v)s.mistakes[id]={count:num(v.count),last:dateValid(v.last)?v.last:dateKey()};}s.history=(Array.isArray(raw.history)?raw.history:[]).filter(x=>x&&LEVELS.includes(x.level)&&dateValid(x.date)).slice(-100).map(x=>({level:x.level,date:x.date,score:num(x.score,100),total:num(x.total,100),sections:Object.fromEntries(['grammar','vocab','reading','listening'].map(k=>[k,{correct:num(x.sections?.[k]?.correct,100),total:num(x.sections?.[k]?.total,100)}]))}));for(const [d,v]of Object.entries(raw.daily||{})){if(dateValid(d)&&v)s.daily[d]=Object.fromEntries(['grammar','vocab','reading','listening','practice'].map(k=>[k,num(v[k])]));}if(raw.plan){s.plan={target:LEVELS.includes(raw.plan.target)?raw.plan.target:'N2',start:LEVELS.includes(raw.plan.start)?raw.plan.start:'N5',minutes:[20,40,60].includes(raw.plan.minutes)?raw.plan.minutes:40};if(LEVELS.indexOf(s.plan.start)>LEVELS.indexOf(s.plan.target))s.plan.target=s.plan.start;}const q=raw.activeQuiz;if(q&&LEVELS.includes(q.level)&&['grammar','vocab','reading','listening','review','exam'].includes(q.mode)&&Array.isArray(q.ids)&&q.ids.length<=30&&q.ids.length>0&&q.ids.every(id=>questionById(id))&&Array.isArray(q.answers)&&q.answers.length<=q.ids.length&&q.answers.every((a,i)=>Number.isInteger(a)&&a>=0&&a<questionById(q.ids[i]).options.length)){s.activeQuiz={level:q.level,mode:q.mode,ids:q.ids,answers:q.answers,index:Math.min(num(q.index,q.ids.length-1),q.answers.length)};}return s;}
let storageOK=true,state=emptyState(),startupStudyRecord=null;try{const raw=localStorage.getItem('hajime-study-v2')||localStorage.getItem('hajime-study-v1');if(raw){startupStudyRecord=JSON.parse(raw);state=cleanState(startupStudyRecord);}}catch{storageOK=false;}
let page='home',level=state.level,kanaMode=0,kanaSet='basic',grammarFilter='全部',search='',wordCursor=0,wordFlipped=false,wordReviewMode='all',toastTimer;
function persist(){try{localStorage.setItem('hajime-study-v2',JSON.stringify(state));}catch{storageOK=false;toast('浏览器无法保存，请在学习档案导出记录。');}}
function touch(kind){const day=dateKey();if(!state.days.includes(day))state.days.push(day);state.daily[day]??={grammar:0,vocab:0,reading:0,listening:0,practice:0};if(kind)state.daily[day][kind]++;persist();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function stopAudio(){if('speechSynthesis'in window)speechSynthesis.cancel();}
function speak(text,rate=.85){if(!('speechSynthesis'in window)){toast('此浏览器不支持语音播放。可以展开原文做精读。');return;}const voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('ja'));if(!voices.length){toast('未检测到日语语音，请在系统设置中安装日语语音包。');return;}stopAudio();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.voice=voices[0];u.rate=rate;u.onerror=()=>toast('语音未能播放，请检查系统日语语音。');speechSynthesis.speak(u);}
if('speechSynthesis'in window)speechSynthesis.getVoices();
function go(p,l=level){if(p==='practice'&&state.activeQuiz)l=state.activeQuiz.level;if(!PAGES.includes(p)||!LEVELS.includes(l))return;stopAudio();level=l;page=p;state.level=l;grammarFilter='全部';search='';wordCursor=0;wordFlipped=false;persist();const hash=`#${l}/${p}`;if(location.hash!==hash)location.hash=hash;else render();}
function fromHash(){const [l,p]=location.hash.slice(1).split('/');if(LEVELS.includes(l))level=l;if(PAGES.includes(p))page=p;if(page==='practice'&&state.activeQuiz)level=state.activeQuiz.level;state.level=level;render();}
window.addEventListener('hashchange',fromHash);
function title(en,name,desc){return `<div class="page-title"><div class="container"><span class="page-level">${level}</span><h1>${name}</h1></div></div>`;}
function compactLearningNotes(html){return html.replace(/<(p|div) class="(hint|grammar-note|completion-note)">([\s\S]*?)<\/\1>/g,(full,tag,kind,body)=>{const text=body.replace(/<[^>]*>/g,'');if(text.length<65||/<(?:button|input|select|textarea|a)\b/.test(body)||/无法|失败/.test(text))return full;return '<details class="learning-help"><summary>学习说明</summary><div>'+body+'</div></details>';});}
const lg=l=>grammar.filter(x=>x.level===l),lw=l=>words.filter(x=>x.level===l),lr=l=>readings.filter(x=>x.level===l),ll=l=>listenings.filter(x=>x.level===l);
function counts(l){const g=lg(l),w=lw(l),r=lr(l),a=ll(l);const done=g.filter(x=>state.completed.includes(x.id)).length+w.filter(x=>state.wordReviews[x.id]?.box>=3).length+[...r,...a].filter(x=>state.textDone.includes(x.id)).length;return{g:g.filter(x=>state.completed.includes(x.id)).length,gt:g.length,w:w.filter(x=>state.wordReviews[x.id]?.box>=3).length,wt:w.length,r:r.filter(x=>state.textDone.includes(x.id)).length,rt:r.length,l:a.filter(x=>state.textDone.includes(x.id)).length,lt:a.length,pct:Math.round(done/(g.length+w.length+r.length+a.length)*100)};}
function nextGrammar(l){return lg(l).find(x=>!state.completed.includes(x.id))||lg(l)[0];}
function renderHome(){return `<div class="hero clean-home"><img class="art" src="landscape.svg" alt="富士山与湖面"><div class="container"><h1>今天，学一点日语。</h1><p>从五十音开始，循序渐进。</p><button class="primary" data-page="plan">继续今日学习 →</button><button class="secondary" data-page="lessons">浏览课程</button></div></div><section class="container"><div class="sectionhead"><h2>选择学习阶段</h2></div><div class="level-cards">${LEVELS.map(l=>{const c=counts(l);return `<button class="level-card ${l===level?'selected':''}" data-level="${l}" data-page="lessons"><span class="level-number">${l}</span><h3>${levelInfo[l].name}</h3><p>${levelInfo[l].focus}</p><div class="bar"><div style="width:${c.pct}%"></div></div><small>已完成 ${c.pct}%</small></button>`;}).join('')}</div></section>`;}
function lessonTiles(items){return `<div class="lesson-list">${items.map(l=>{const learned=state.completed.includes(l.id);return `<button class="lesson-tile ${learned?'is-learned':'is-unlearned'}" data-lesson="${l.id}"><span class="lesson-topline"><span class="label">${l.level} / ${l.topic}</span><span class="lesson-status ${learned?'status-learned':'status-unlearned'}"><span aria-hidden="true">${learned?'✓':'○'}</span> ${learned?'已学':'未学'}</span></span><h3>${l.title}</h3><p>${l.desc}</p><span class="meta"><span>${learned?'复习本课':'开始学习'}</span><span aria-hidden="true">→</span></span></button>`;}).join('')}</div>`;}
function renderLessons(isGrammar=false){const list=lg(level);return title('GRAMMAR IS THE FOUNDATION',isGrammar?'语法课堂':'系统课程',`${levelInfo[level].focus}。当前 ${list.length} 节自编核心语法课，按学习进阶分层。`)+`<section class="container page-section">${isGrammar?`<div class="filterrow"><label>搜索语法<input id="grammarSearch" type="search" placeholder="句型、接续或中文含义" value="${esc(search)}"></label><div class="toolbar">${['全部',...new Set(list.map(x=>x.topic))].map(t=>`<button class="chip ${t===grammarFilter?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div></div><div id="tiles">${lessonTiles(list)}</div>`:`<div class="hint">推荐顺序：每学一个语法模块，搭配词汇、阅读和听力。完成课程表示「已学」，不等于已经掌握全部等级要求。</div>${Array.from({length:Math.ceil(list.length/4)},(_,i)=>`<div class="module"><div class="module-title"><span>MODULE ${String(i+1).padStart(2,'0')}</span><h3>${[...new Set(list.slice(i*4,i*4+4).map(x=>x.topic))].join(' · ')}</h3><small>${list.slice(i*4,i*4+4).filter(x=>state.completed.includes(x.id)).length} / ${list.slice(i*4,i*4+4).length} 已学</small></div>${lessonTiles(list.slice(i*4,i*4+4))}</div>`).join('')}<div class="next-path"><p>学习完语法后，把句型放回真实的句子里。</p><button class="secondary" data-page="vocab">词汇巩固 →</button><button class="secondary" data-page="reading">阅读应用 →</button><button class="secondary" data-page="listening">听力应用 →</button></div>`}</section>`;}
function openLesson(id){const l=grammar.find(x=>x.id===id);if(!l)return;const group=lg(l.level),next=group[group.indexOf(l)+1];$('#lessonBody').innerHTML=`<span class="label">${l.level} / ${l.topic}</span><h2>${l.title}</h2><h3>理解规则与接续</h3><p>${l.rule}</p><h3>观察例句</h3>${l.examples.map(([ja,zh])=>`<div class="example"><b lang="ja">${ja}</b><button class="speak" data-speak="${esc(ja)}">▷ 听发音</button>${romanExample(ja,zh)}<small>${zh}</small></div>`).join('')}<h3>从理解到表达</h3><p>${l.tip}</p><div class="exercise"><span class="label">CHECK YOUR UNDERSTANDING</span><p>${l.q}</p><div class="answers">${l.options.map((o,i)=>`<button data-inline-answer="${i}" data-question="${l.id}">${o}</button>`).join('')}</div><div class="feedback" role="status"></div></div><div class="lesson-actions"><button class="primary" data-complete="${l.id}">${state.completed.includes(l.id)?'已学过 · 返回':'标记已学 ✓'}</button>${next?`<button class="secondary" data-nextlesson="${next.id}" data-current="${l.id}">学完并进入下一课 →</button>`:''}</div><p class="completion-note">试着替换例句中的人物和事物，自己说一句。正确答题与已学记录分别保存。</p>`;if(!$('#lessonDialog').open)$('#lessonDialog').showModal();$('#lessonDialog').scrollTop=0;}
const contracted=[['きゃきゅきょ','キャキュキョ',['kya','kyu','kyo']],['しゃしゅしょ','シャシュショ',['sha','shu','sho']],['ちゃちゅちょ','チャチュチョ',['cha','chu','cho']],['にゃにゅにょ','ニャニュニョ',['nya','nyu','nyo']],['ひゃひゅひょ','ヒャヒュヒョ',['hya','hyu','hyo']],['みゃみゅみょ','ミャミュミョ',['mya','myu','myo']],['りゃりゅりょ','リャリュリョ',['rya','ryu','ryo']],['ぎゃぎゅぎょ','ギャギュギョ',['gya','gyu','gyo']],['じゃじゅじょ','ジャジュジョ',['ja','ju','jo']],['びゃびゅびょ','ビャビュビョ',['bya','byu','byo']],['ぴゃぴゅぴょ','ピャピュピョ',['pya','pyu','pyo']]];
function renderKana(){const rows=kanaSet==='basic'?kanaRows:kanaSet==='voiced'?voicedRows:contracted;return title('THE FIRST SOUND','五十音与发音','先认识假名，再把字音放回单词。两个字母不一定是两个拍。')+`<section class="container page-section"><div class="toolbar">${['平假名','片假名'].map((s,i)=>`<button class="chip ${kanaMode===i?'selected':''}" data-kanamode="${i}">${s}</button>`).join('')}${[['basic','清音'],['voiced','浊音 / 半浊音'],['contracted','拗音']].map(([s,n])=>`<button class="chip ${kanaSet===s?'selected':''}" data-kanaset="${s}">${n}</button>`).join('')}</div><div class="hint">点读使用系统日语语音，需安装日语语音包。拗音如「きゃ」是一个拍；「きや」是两个拍。を作助词通常读 o，は作助词读 wa。</div><div class="kana-grid ${kanaSet==='contracted'?'three':''}">${rows.map(r=>(kanaSet==='contracted'?Array.from({length:3},(_,i)=>r[kanaMode].slice(i*2,i*2+2)):Array.from(r[kanaMode])).map((k,i)=>k===' '?'<div class="kana-cell empty"></div>':`<button class="kana-cell" data-kana="${k}" data-base="${kanaSet==='basic'?r[0][i]:''}"><b lang="ja">${k}</b><small>${r[2][i]}</small></button>`).join('')).join('')}</div><div class="pronunciation-notes"><h3>别漏掉这些发音规则</h3><p><b>长音：</b>保留两个拍，如 おばさん（阿姨）与 おばあさん（奶奶）。片假名常用「ー」表示长音。</p><p><b>促音：</b>小「っ」表示一拍的停顿，如 きって（邮票）。不要读成独立的つ。</p><p><b>拨音：</b>「ん」占一拍，实际音色受后面的音影响。跟读单词比只听孤立音更有效。</p><button class="secondary" data-speak="おばさん。おばあさん。きって。きいて。">聆听长音与促音示例 ▷</button></div></section>`;}
function dueWords(){return lw(level).filter(w=>state.wordReviews[w.id]&&state.wordReviews[w.id].due<=dateKey());}
function visibleWords(){const guided=typeof guidedWords==='function'?guidedWords():null;return (guided|| (wordReviewMode==='due'?dueWords():lw(level))).filter(w=>[w.word,w.reading,w.meaning].some(x=>x.includes(search.trim())));}
function wordCard(){const list=visibleWords();if(!list.length)return `<div class="empty-state">${wordReviewMode==='due'?'今天没有待复习词汇。可以切回全部词汇，或继续阅读训练。':'未找到匹配词汇。'}<button class="more" data-reviewmode="all">查看全部词汇 →</button></div>`;wordCursor=Math.min(wordCursor,list.length-1);const w=list[wordCursor],r=state.wordReviews[w.id];return `<div class="flashcard"><span class="label">${wordCursor+1} / ${list.length}</span><span class="pos-badge">${esc(w.pos)}</span><h2 lang="ja">${w.word}</h2>${wordFlipped?`<div class="word-reading" lang="ja">${w.reading}</div>${romanLine(w.reading)}<p class="vocab-meaning"><span class="vocab-field">词义</span><strong>${esc(w.meaning)}</strong></p><button class="speak" data-speak="${w.reading}">▷ 听读音</button><p class="completion-note">${r?`复习盒 ${r.box} / 6 · 下次 ${r.due}`:'尚未复习'} · 连续记住三次后记入「稳定复习」</p><div class="word-actions"><button class="secondary" data-wordrate="0" data-word="${w.id}">还不熟 · 今天再看</button><button class="primary" data-wordrate="1" data-word="${w.id}">记住了 · 安排复习 ✓</button></div>`:`<p>先回忆读音和中文含义，再翻开答案。</p><button class="primary" id="flipWord">显示读音与词义 →</button>`}<div class="card-pagination"><button id="prevWord">← 上一个</button><button id="nextWord">下一个 →</button></div></div>`;}
function wordRowsHtml(){return visibleWords().map(w=>`<tr><td><button data-speak="${w.reading}" lang="ja">${w.word} ▷</button></td><td lang="ja">${w.reading}${romanLine(w.reading)}</td><td><div class="vocab-meaning"><span class="vocab-field">词义</span><strong>${esc(w.meaning)}</strong></div><div class="vocab-pos"><span class="vocab-field">词性</span><span class="pos-badge">${esc(w.pos)}</span></div></td><td>${state.wordReviews[w.id]?.box>=3?'✓ 稳定':state.wordReviews[w.id]?'复习中':'未开始'}</td></tr>`).join('');}
function renderVocab(){return title('WORDS IN CONTEXT','词汇与汉字',`${level} 核心词卡 ${lw(level).length} 张。认读汉字与假名、回忆词义，再用间隔复习巩固。`)+`<section class="container page-section"><div class="filterrow"><label>查找词汇<input id="wordSearch" type="search" placeholder="汉字、假名或中文" value="${esc(search)}"></label><div class="toolbar"><button class="chip ${wordReviewMode==='all'?'selected':''}" data-reviewmode="all">全部词汇</button><button class="chip ${wordReviewMode==='due'?'selected':''}" data-reviewmode="due">今日待复习 ${dueWords().length}</button></div></div><div id="wordCard">${wordCard()}</div><div class="hint">这是各阶段的核心示例词库，完整 JLPT 备考还需扩大词汇量。点击「记住了」后按 1、3、7、14、30、60 天的间隔安排；「还不熟」回到今天。以词为单位记汉字读音，同一个汉字在不同词中可能读音不同。</div><div class="word-table"><table><thead><tr><th>词汇</th><th>读音</th><th>词义</th><th>复习</th></tr></thead><tbody id="wordRows">${wordRowsHtml()}</tbody></table></div></section>`;}
function answerBlock(q){return `<div class="exercise"><span class="label">UNDERSTAND THE MESSAGE</span><p>${q.q}</p><div class="answers">${q.options.map((o,i)=>`<button data-inline-answer="${i}" data-question="${q.id}">${o}</button>`).join('')}</div><div class="feedback" role="status"></div></div>`;}
function renderTexts(type){const isListen=type==='listening',items=isListen?ll(level):lr(level);return title(isListen?'LISTEN · UNDERSTAND · REPLAY':'READ · UNDERSTAND · REFLECT',isListen?'听力训练':'阅读训练',isListen?'先听对话，记下关键信息，再作答并展开原文。所有听力均为系统合成语音。':'先读日语短文，抓住问题需要的信息；作答后核对解析，再用翻译检查理解。')+`<section class="container page-section"><div class="hint">${isListen?'支持慢速、标准与稍快播放；系统需有日语语音包。合成语音训练不替代真人录音和官方听力样题。':'短文为自编练习。建议先不看翻译；N3 注意段落关系，N2 注意转折、限定和作者立场。'}</div><div class="text-list">${items.map(q=>`<article class="text-card"><div class="text-title"><span class="label">${level} · ${isListen?'LISTENING':'READING'}</span><h2>${q.title}</h2><span class="done-label">${state.textDone.includes(q.id)?'✓ 已完成':'未完成'}</span></div>${isListen?`<div class="audio-controls"><button class="primary" data-audio="${q.id}">▷ 播放对话</button><label>语速 <select data-speed="${q.id}"><option value="0.75">慢速</option><option value="0.95" ${level==='N2'?'selected':''}>标准</option><option value="1.1">稍快</option></select></label><button class="secondary" data-stop-audio="true">停止</button></div><details><summary>听过后，展开日语原文与翻译</summary><p class="japanese-text" lang="ja">${q.text}</p><p class="translation">${q.translation}</p></details>`:`<p class="japanese-text" lang="ja">${q.text}</p><details><summary>查看中文翻译</summary><p class="translation">${q.translation}</p></details>`}${answerBlock(q)}<button class="more text-complete" data-textdone="${q.id}" disabled>完成练习后记录进度 ✓</button></article>`).join('')}</div></section>`;}
function wordQuestion(w){const others=words.filter(x=>x.level===w.level&&x.meaning!==w.meaning),seed=words.indexOf(w),distractors=[...new Set(others.slice(seed%25,seed%25+8).map(x=>x.meaning))].slice(0,3);const opts=[w.meaning,...distractors],shift=seed%opts.length,options=opts.slice(shift).concat(opts.slice(0,shift));return{id:w.id,type:'vocab',level:w.level,title:'词义辨认',q:`「${w.word}（${w.reading}）」的意思是？`,options,answer:options.indexOf(w.meaning),why:`${w.word}（${w.reading}）：${w.meaning}。词性：${w.pos}。`};}
function questionById(id){const g=grammar.find(x=>x.id===id);if(g)return{...g,type:'grammar'};const w=words.find(x=>x.id===id);if(w)return wordQuestion(w);const t=[...readings,...listenings].find(x=>x.id===id);return t?{...t,type:t.type==='r'?'reading':'listening'}:null;}
function recordAnswer(q,a){state.attempts++;const ok=a===q.answer;if(ok){state.correct++;delete state.mistakes[q.id];}else state.mistakes[q.id]={count:(state.mistakes[q.id]?.count||0)+1,last:dateKey()};touch('practice');return ok;}
function shuffled(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function startQuiz(mode){if(state.activeQuiz){toast('先继续或结束当前练习，再开始新的一组。');return;}const maps={grammar:lg(level),vocab:lw(level),reading:lr(level),listening:ll(level)};let ids;if(mode==='exam')ids=[...shuffled(maps.grammar).slice(0,8),...shuffled(maps.vocab).slice(0,6),...shuffled(maps.reading).slice(0,3),...shuffled(maps.listening).slice(0,3)].map(x=>x.id);else if(mode==='review')ids=shuffled(Object.keys(state.mistakes).filter(id=>questionById(id)?.level===level)).slice(0,20);else ids=shuffled(maps[mode]||[]).slice(0,10).map(x=>x.id);if(!ids.length){toast('当前等级没有待复习错题。');return;}state.activeQuiz={level,mode,ids,answers:[],index:0};persist();render(false);}
function quizView(){const z=state.activeQuiz,q=questionById(z.ids[z.index]),answered=z.answers.length>z.index;return `<div class="quizbox"><div class="sectionhead"><span class="label">${z.level} · ${z.mode==='exam'?'阶段测评':'专项练习'} / ${z.index+1} / ${z.ids.length}</span><button id="endQuiz">结束并查看结果</button></div><div class="bar"><div style="width:${(z.index+1)/z.ids.length*100}%"></div></div>${q.type==='reading'?`<p class="japanese-text" lang="ja">${q.text}</p>`:q.type==='listening'?`<div class="audio-controls"><button class="primary" data-audio="${q.id}">▷ 播放题目</button><label>语速 <select data-speed="${q.id}"><option value="0.85">慢速</option><option value="1" selected>标准</option></select></label></div><details><summary>查看原文（辅助学习，会影响自测真实性）</summary><p class="japanese-text" lang="ja">${q.text}</p></details>`:''}<h2>${q.q}</h2><div class="answers">${q.options.map((o,i)=>`<button data-quizanswer="${i}" ${answered?'disabled':''} class="${answered&&i===q.answer?'correct':answered&&i===z.answers[z.index]?'wrong':''}">${o}</button>`).join('')}</div>${answered?`<div class="feedback" role="status">${z.answers[z.index]===q.answer?'✓ 回答正确。':'再记一次：'} ${q.why}</div><button class="primary" id="nextQuestion">${z.index===z.ids.length-1?'完成并查看结果 ✓':'下一题 →'}</button>`:'<p class="completion-note">选择答案后查看解析。离开页面后可继续，刷新不会丢失已提交答案。</p>'}</div>`;}
const typeNames={grammar:'语法',vocab:'词汇',reading:'阅读',listening:'听力'};
function finishQuiz(){const z=state.activeQuiz;if(!z)return;const sections=Object.fromEntries(Object.keys(typeNames).map(k=>[k,{correct:0,total:0}]));z.answers.forEach((a,i)=>{const q=questionById(z.ids[i]);sections[q.type].total++;if(a===q.answer)sections[q.type].correct++;});const total=z.answers.length,correct=Object.values(sections).reduce((n,s)=>n+s.correct,0),score=total?Math.round(correct/total*100):0,complete=total===z.ids.length;if(z.mode==='exam'&&complete)state.history.push({level:z.level,date:dateKey(),score,total,sections});state.history=state.history.slice(-100);state.activeQuiz=null;persist();$('#view').innerHTML=title('LEARN FROM YOUR RESULTS',complete?'本组练习完成':'本组练习已结束',`${z.level} · 已作答 ${total} / ${z.ids.length} 题。${z.mode==='exam'&&!complete?'未完成的测评不计入阶段记录。':''}`)+`<section class="container"><div class="result-score"><b>${score}<small>%</small></b><p>本组答对 ${correct} / ${total} 题</p></div><div class="result-sections">${Object.entries(sections).map(([k,s])=>`<div class="stat"><b>${s.correct}<span> / ${s.total}</span></b><span>${typeNames[k]} · ${s.total===0?'本组未测试':s.correct/s.total<.8?'建议复习':'继续巩固'}</span></div>`).join('')}</div><div class="hint">这是本站训练题的正确率，不是 JLPT 换算分数，也不代表考试合格概率。建议结合官方样题和完整备考材料检查能力。</div><div class="toolbar"><button class="primary" data-page="practice">返回练习中心 →</button><button class="secondary" data-page="progress">查看档案 →</button></div></section>`;stopAudio();}
function renderPractice(){const mistakes=Object.keys(state.mistakes).map(questionById).filter(q=>q?.level===level);return title('PRACTICE · ASSESS · REVIEW','练习与阶段测评','选择专项练习，或完成一组 20 题测评。每次错误都会收录到错题本。')+`<section class="container page-section">${state.activeQuiz?quizView():`<div class="practice-grid">${[['grammar','语法巩固','接续形式与句型意义'],['vocab','词义辨认','假名、汉字和词义'],['reading','阅读理解','定位、主旨与逻辑'],['listening','听力理解','先听，再抓关键信息']].map(([m,n,d])=>`<button class="practice-card" data-startquiz="${m}"><span class="label">${level} / PRACTICE</span><h3>${n}</h3><p>${d}</p><span class="more">开始练习 →</span></button>`).join('')}</div><div class="exam-banner"><div><span class="label">CHECK YOUR PROGRESS</span><h2>${level} 阶段测评</h2><p>语法 8 题 + 词汇 6 题 + 阅读 3 题 + 听力 3 题。<br>自编学习测评，可随时暂停；不模拟真实考试计时和评分。</p></div><button class="primary" data-startquiz="exam">开始 20 题测评 →</button></div><div class="sectionhead"><h2>错题本 <small>${mistakes.length} ITEMS</small></h2><button data-startquiz="review">复习当前等级错题 →</button></div>${mistakes.length?`<div class="mistake-list">${mistakes.map(q=>`<div><span class="label">${typeNames[q.type]} · 累计 ${state.mistakes[q.id].count} 次错误</span><h3>${q.q}</h3><details><summary>查看正确答案与解释</summary><p>${q.options[q.answer]}</p><p>${q.why}</p></details></div>`).join('')}</div>`:'<div class="empty-state">当前等级暂无错题。先完成专项练习，再回来复习。</div>'}`}<div class="resource-links"><a href="https://www.jlpt.jp/e/samples/forlearners.html" target="_blank" rel="noopener">JLPT 官方样题 ↗</a><a href="https://www.jlpt.jp/e/about/levelsummary.html" target="_blank" rel="noopener">官方等级能力说明 ↗</a></div></section>`;}
function planTasks(){const m=state.plan.minutes;return{grammar:m===20?1:2,vocab:m===20?5:m===40?10:15,reading:1,listening:1,practice:m===20?3:m===40?5:10};}
function renderPlan(){const t=planTasks(),d=state.daily[dateKey()]||{},start=LEVELS.indexOf(state.plan.start),end=LEVELS.indexOf(state.plan.target);return title('SMALL STEPS, EVERY DAY','我的学习计划','按时间安排每天的学习，并根据完成记录调整下一步。计划不承诺固定时间考过。')+`<section class="container page-section"><form id="planForm" class="plan-settings"><label>从哪个阶段开始<select name="start">${LEVELS.map(l=>`<option ${l===state.plan.start?'selected':''}>${l}</option>`).join('')}</select></label><label>目标等级<select name="target">${LEVELS.map(l=>`<option ${l===state.plan.target?'selected':''}>${l}</option>`).join('')}</select></label><label>每天可用时间<select name="minutes">${[20,40,60].map(n=>`<option value="${n}" ${n===state.plan.minutes?'selected':''}>${n} 分钟</option>`).join('')}</select></label><button class="primary" type="submit">保存计划 ✓</button></form><div class="hint">${state.plan.minutes} 分钟是时间预算；任务数量是建议，可按实际难度调整。今日统计包含各等级完成量。语法和词汇熟练度需要持续验证。</div><div class="sectionhead"><h2>今日任务 <small>${dateKey()}</small></h2></div><div class="task-list">${[['grammar','学习语法','grammar',t.grammar],['vocab','复习词汇','vocab',t.vocab],['reading','阅读短文','reading',t.reading],['listening','听力精听','listening',t.listening],['practice','练习作答','practice',t.practice]].map(([k,n,p,goal])=>`<div class="task-row"><span class="task-check">${(d[k]||0)>=goal?'✓':'○'}</span><div><strong>${n}</strong><small>今天 ${d[k]||0} / 建议 ${goal} ${k==='vocab'?'张卡':k==='practice'?'题':k==='grammar'?'课':'篇'}</small></div><button class="more" data-page="${p}">去完成 →</button></div>`).join('')}</div><div class="sectionhead" style="margin-top:36px"><h2>我的进阶路线 <small>${state.plan.start} → ${state.plan.target}</small></h2></div><div class="plan-route">${LEVELS.slice(start,end+1).map(l=>`<article><b>${l}</b><div><h3>${levelInfo[l].name}</h3><p>${levelInfo[l].outcome}</p><p>${lg(l).length} 节语法 · ${lw(l).length} 张词卡 · ${lr(l).length} 篇阅读 · ${ll(l).length} 段听力</p></div><button class="secondary" data-level="${l}" data-page="lessons">进入 →</button></article>`).join('')}</div></section>`;}
function renderProgress(){const all=LEVELS.map(counts),latest=[...state.history].reverse().find(x=>x.level===level),c=counts(level),ready=c.g/c.gt>=.8&&c.w/c.wt>=.7&&c.r===c.rt&&c.l===c.lt&&(latest?.score||0)>=80;return title('YOUR LEARNING ARCHIVE','学习档案','保留每个阶段的学习与复习记录。导出备份，在另一个浏览器导入继续。')+`<section class="container page-section"><div class="stats"><div class="stat"><b>${state.completed.length}<span> / ${grammar.length}</span></b><span>已学核心语法课</span></div><div class="stat"><b>${state.attempts?Math.round(state.correct/state.attempts*100):0}<span>%</span></b><span>累计正确率 · ${state.attempts} 次首次作答</span></div><div class="stat"><b>${state.days.length}</b><span>累计学习天数</span></div></div><div class="toolbar"><button class="secondary" id="exportProgress">导出学习记录 ↗</button><button class="secondary" id="importProgress">导入学习记录 ↙</button><button class="secondary" data-page="plan">调整学习计划 →</button></div><p class="completion-note">${storageOK?'进度先保存在当前浏览器；点击顶部「登录 / 同步」，登录同一账号后自动跨设备同步。导入会合并已学课程，采用备份中的复习安排和计划。':'当前浏览器无法持久保存，请及时导出。'}原入门版的课程记录会自动迁移。</p><div class="level-progress">${LEVELS.map((l,i)=>`<article><h3>${l} <small>${levelInfo[l].name}</small></h3><div class="bar"><div style="width:${all[i].pct}%"></div></div><p>语法 ${all[i].g}/${all[i].gt} · 稳定词卡 ${all[i].w}/${all[i].wt}<br>阅读 ${all[i].r}/${all[i].rt} · 听力 ${all[i].l}/${all[i].lt}</p><button class="more" data-level="${l}" data-page="lessons">继续学习 →</button></article>`).join('')}</div><div class="hint">${ready?`✓ ${level} 达到本站继续进阶的建议门槛。可进入下一阶段，同时继续补充官方材料。`:`${level} 进阶建议：语法已学达到 80%、稳定词卡达到 70%、本站阅读听力全部完成，且最近一次阶段测评正确率达到 80%。`}<br>这些是本站学习建议，不代表 JLPT 合格标准或完整内容覆盖率。</div><div class="sectionhead"><h2>阶段测评记录 <small>ASSESSMENT HISTORY</small></h2></div>${state.history.length?`<div class="word-table"><table><thead><tr><th>日期</th><th>等级</th><th>正确率</th><th>分项（正确 / 题数）</th></tr></thead><tbody>${[...state.history].reverse().map(h=>`<tr><td>${h.date}</td><td>${h.level}</td><td>${h.score}%</td><td>${Object.entries(typeNames).map(([k,n])=>`${n} ${h.sections[k]?.correct||0}/${h.sections[k]?.total||0}`).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">还没有完整的阶段测评记录。完成一组 20 题测评后会显示各项成绩。</div>'}</section>`;}
function render(scroll=true){const views={home:renderHome,kana:renderKana,lessons:()=>renderLessons(false),grammar:()=>renderLessons(true),vocab:renderVocab,reading:()=>renderTexts('reading'),listening:()=>renderTexts('listening'),practice:renderPractice,progress:renderProgress,plan:renderPlan};$('#view').innerHTML=compactLearningNotes(views[page]());$('#levelTabs').innerHTML=LEVELS.map(l=>`<button data-level="${l}" class="${level===l?'selected':''}" aria-pressed="${level===l}">${l}</button>`).join('');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function markLesson(id){if(!state.completed.includes(id)){state.completed.push(id);touch('grammar');}persist();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.page||d.level){go(d.page||page,d.level||level);return;}if(d.lesson)openLesson(d.lesson);if(d.speak)speak(d.speak);
if(d.kana){speak(d.kana);if(d.base&&!state.seen.includes(d.base)){state.seen.push(d.base);touch();}}
if(d.kanamode!==undefined){kanaMode=Number(d.kanamode);render(false);}if(d.kanaset){kanaSet=d.kanaset;render(false);}
if(d.filter){grammarFilter=d.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));filterGrammar();}
if(d.inlineAnswer!==undefined){const q=questionById(d.question),box=b.closest('.exercise');if(box.dataset.answered)return;box.dataset.answered='yes';const a=Number(d.inlineAnswer),ok=recordAnswer(q,a);box.querySelectorAll('.answers button').forEach((x,i)=>{x.disabled=true;x.classList.toggle('correct',i===q.answer);x.classList.toggle('wrong',i===a&&!ok);});box.querySelector('.feedback').textContent=`${ok?'✓ 回答正确。':'再记一次：'} ${q.why}`;const doneButton=b.closest('.text-card')?.querySelector('[data-textdone]');if(doneButton){doneButton.disabled=false;doneButton.textContent='已理解解析，记录完成 ✓';}}
if(d.complete){markLesson(d.complete);stopAudio();$('#lessonDialog').close();render(false);toast('课程已记入学习档案。');}
if(d.nextlesson){markLesson(d.current);stopAudio();openLesson(d.nextlesson);}
if(b.classList.contains('close')){stopAudio();$('#lessonDialog').close();}
if(d.reviewmode){wordReviewMode=d.reviewmode;wordCursor=0;wordFlipped=false;render(false);}
if(b.id==='flipWord'){wordFlipped=true;$('#wordCard').innerHTML=wordCard();const w=visibleWords()[wordCursor];if(w)speak(w.reading);}
if(b.id==='nextWord'||b.id==='prevWord'){const list=visibleWords();if(list.length)wordCursor=(wordCursor+(b.id==='nextWord'?1:-1)+list.length)%list.length;wordFlipped=false;$('#wordCard').innerHTML=wordCard();}
if(d.wordrate!==undefined){const w=words.find(x=>x.id===d.word);if(!w)return;const old=state.wordReviews[w.id]||{box:0},box=d.wordrate==='1'?(old.last===dateKey()?Math.max(old.box,1):Math.min(old.box+1,6)):0;state.wordReviews[w.id]={box,due:box?afterDays([1,3,7,14,30,60][box-1]):dateKey(),last:dateKey()};if(old.last!==dateKey())touch('vocab');else persist();wordFlipped=false;if(wordReviewMode==='all'){const list=visibleWords();wordCursor=list.length?(wordCursor+1)%list.length:0;}render(false);}
if(d.audio){const q=questionById(d.audio),s=$(`[data-speed="${d.audio}"]`);if(q)speak(q.text,Number(s?.value||.85));}if(d.stopAudio)stopAudio();
if(d.textdone&&!b.disabled){if(!state.textDone.includes(d.textdone)){state.textDone.push(d.textdone);touch(questionById(d.textdone).type);}b.textContent='✓ 已完成并保存';b.disabled=true;}
if(d.startquiz)startQuiz(d.startquiz);
if(d.quizanswer!==undefined){const z=state.activeQuiz;if(!z||z.answers.length>z.index)return;const q=questionById(z.ids[z.index]),a=Number(d.quizanswer);recordAnswer(q,a);z.answers.push(a);persist();render(false);}
if(b.id==='nextQuestion'){const z=state.activeQuiz;if(!z||z.answers.length<=z.index)return;stopAudio();if(z.index===z.ids.length-1)finishQuiz();else{z.index++;persist();render(false);}}
if(b.id==='endQuiz')finishQuiz();
if(b.id==='exportProgress'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}));a.href=u;a.download=`初见日语-学习记录-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
if(b.id==='importProgress')$('#importFile').click();
});
function filterGrammar(){const items=lg(level).filter(l=>(grammarFilter==='全部'||l.topic===grammarFilter)&&[l.title,l.rule,l.topic].some(s=>s.includes(search.trim())));$('#tiles').innerHTML=items.length?lessonTiles(items):'<div class="empty-state">未找到匹配语法。试试中文含义或日语句型。</div>';}
document.addEventListener('input',e=>{if(e.target.id==='grammarSearch'){search=e.target.value;filterGrammar();}if(e.target.id==='wordSearch'){search=e.target.value;wordCursor=0;wordFlipped=false;$('#wordCard').innerHTML=wordCard();$('#wordRows').innerHTML=wordRowsHtml();}});
document.addEventListener('submit',e=>{if(e.target.id!=='planForm')return;e.preventDefault();const f=new FormData(e.target),start=f.get('start'),target=f.get('target');if(LEVELS.indexOf(start)>LEVELS.indexOf(target)){toast('目标等级应与起点相同或更高。');return;}state.plan={start,target,minutes:Number(f.get('minutes'))};persist();render(false);toast('计划已保存。');});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('记录文件过大');const imported=cleanState(JSON.parse(await file.text()));imported.completed=[...new Set([...state.completed,...imported.completed])];imported.seen=[...new Set([...state.seen,...imported.seen])];imported.textDone=[...new Set([...state.textDone,...imported.textDone])];imported.days=[...new Set([...state.days,...imported.days])];if(state.attempts>imported.attempts){imported.attempts=state.attempts;imported.correct=state.correct;}imported.wordReviews={...state.wordReviews,...imported.wordReviews};imported.mistakes={...state.mistakes,...imported.mistakes};imported.history=[...new Map([...state.history,...imported.history].map(h=>[JSON.stringify(h),h])).values()].slice(-100);imported.daily={...state.daily,...imported.daily};if(typeof mergeN5Course==='function')imported.course=mergeN5Course(state.course,imported.course);if(typeof mergeStudyExtras==='function')mergeStudyExtras(state,imported);state=imported;level=state.level;persist();go('progress');toast('已导入并合并学习记录。');}catch{toast('导入失败：请选择本站导出的有效 JSON 记录。');}e.target.value='';});
$('#lessonDialog').addEventListener('click',e=>{if(e.target===$('#lessonDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){stopAudio();e.target.close();}}});$('#lessonDialog').addEventListener('cancel',stopAudio);
